model_sql:
SELECT employee_id, first_name, last_name, email, department_id, manager_id, hire_date, created_at 
FROM employees 
WHERE YEAR(hire_date) = 2023;

SELECT product_id, product_name, category_id, price, stock_qty
FROM products
WHERE product_id NOT IN (
    SELECT DISTINCT product_id 
    FROM order_items
);
